using System;
using System.Linq;
using WoWProbe;
class CampaignPreflightTests
{
    static int passed,failed;static void Test(string n,Action a){try{a();passed++;Console.WriteLine("PASS "+n);}catch(Exception e){failed++;Console.WriteLine("FAIL "+n+": "+e.Message);}}static void Assert(bool b){if(!b)throw new Exception("assertion failed");}
    static CampaignPlan Ready(){var p=CampaignFixtures.Plan();p.Settings.BindingsConfirmed=p.Settings.UiConfirmed=p.Settings.AutoResumeConfirmed=p.Battle.BindingsConfirmed=p.Battle.Calibration.Confirmed=p.Battle.ApproachPositionConfirmed=true;return p;}
    static bool Block(PreflightReport r,string code){return r.Checks.Any(c=>c.Code==code&&c.State=="block");}
    static OperationObservation SavedMonster(CampaignPlan p)
    {
        var o=CampaignFixtures.Sample();var f=o.Farm;f.TargetExists=f.TargetIdentityKnown=f.NameHashKnown=f.TargetDeadKnown=f.AttackabilityKnown=f.TargetCanAttack=true;f.TargetToken=303;f.TargetNameHash=p.Battle.Targets[0].NameHash;f.TargetHealth=100;f.RangeKnown=f.TargetInRange=true;f.RangeSlot=p.Battle.RangeSlot;return o;
    }
    static int Main()
    {
        Test("ready current state may retain future runtime checks without claiming game acceptance",delegate{var r=CampaignPreflight.Evaluate(Ready(),CampaignFixtures.Sample(),false,"");Assert(r.ReadyToArm&&r.Checks.Any(c=>c.State=="pending"));Assert(r.ToMarkdown().Contains("实机验收")&&r.ToMarkdown().Contains("pending"));});
        Test("imported unconfirmed plans cannot become ready automatically",delegate{var p=CampaignFixtures.Plan();var r=CampaignPreflight.Evaluate(p,CampaignFixtures.Sample(),false,"");Assert(!r.ReadyToArm&&Block(r,"bindings")&&Block(r,"calibration")&&Block(r,"resume"));});
        Test("plan errors and missing observations produce actionable blocked results",delegate{var p=Ready();p.VendorRoute.MapId++;var r=CampaignPreflight.Evaluate(p,null,false,"");Assert(!r.ReadyToArm&&Block(r,"plan")&&Block(r,"data"));Assert(!CampaignPreflight.Evaluate(null,null,true,"").ReadyToArm);});
        Test("global input fault freshness and sequence are checked without mutation",delegate{var p=Ready();var before=p.Fingerprint();var o=CampaignFixtures.Sample();o.Sequence++;var r=CampaignPreflight.Evaluate(p,o,true,"");Assert(Block(r,"input_lock")&&Block(r,"data")&&p.Fingerprint()==before);});
        Test("wrong map window geometry and invalid coordinates block startup",delegate{var o=CampaignFixtures.Sample();o.MapId++;o.LayoutToken=0;o.Farm.X=Double.NaN;var r=CampaignPreflight.Evaluate(Ready(),o,false,"");Assert(Block(r,"map")&&Block(r,"geometry")&&Block(r,"position"));});
        Test("combat cursor items confirmations and incoming resurrection block",delegate{var o=CampaignFixtures.Sample();o.Farm.InCombat=true;o.CursorEmpty=false;o.ConfirmationVisible=true;o.IncomingResurrection=true;var r=CampaignPreflight.Evaluate(Ready(),o,false,"");Assert(Block(r,"combat")&&Block(r,"cursor")&&Block(r,"popup")&&Block(r,"resurrection_invite"));});
        Test("alive start must join original recorded anchor",delegate{var o=CampaignFixtures.Sample();o.Farm.X=.8;Assert(Block(CampaignPreflight.Evaluate(Ready(),o,false,""),"route_connection"));});
        Test("actual dead state requires verified release not guessed coordinates",delegate{var o=CampaignFixtures.Sample();o.Farm.PlayerDead=true;o.Farm.Health=0;var r=CampaignPreflight.Evaluate(Ready(),o,false,"");Assert(Block(r,"release"));o.ReleaseVisible=o.ReleaseEnabled=true;Assert(!Block(CampaignPreflight.Evaluate(Ready(),o,false,""),"release"));});
        Test("ghost startup requires actual corpse and recorded graveyard route",delegate{var o=CampaignFixtures.Sample();o.Farm.PlayerGhost=true;o.Farm.Health=0;o.Farm.X=.47;var r=CampaignPreflight.Evaluate(Ready(),o,false,"");Assert(Block(r,"corpse"));o.CorpseKnown=true;o.CorpseX=.515;o.CorpseY=.5;r=CampaignPreflight.Evaluate(Ready(),o,false,"");Assert(!Block(r,"corpse")&&!Block(r,"route_connection"));});
        Test("current saved target range and approach data are verified",delegate{var p=Ready();var o=CampaignFixtures.Sample();var f=o.Farm;f.TargetExists=f.TargetIdentityKnown=f.NameHashKnown=f.TargetDeadKnown=f.AttackabilityKnown=f.TargetCanAttack=true;f.TargetToken=303;f.TargetNameHash=p.Battle.Targets[0].NameHash;f.TargetHealth=100;var r=CampaignPreflight.Evaluate(p,o,false,"");Assert(Block(r,"target_range"));f.RangeKnown=true;f.RangeSlot=p.Battle.RangeSlot;r=CampaignPreflight.Evaluate(p,o,false,"");Assert(Block(r,"target_position"));f.TargetInRange=true;Assert(!Block(CampaignPreflight.Evaluate(p,o,false,""),"target_position"));});
        Test("current saved monster blocks unknown configured action slots",delegate{var p=Ready();p.Battle.SkillSequence="12";var o=SavedMonster(p);o.Farm.ActionsKnown=false;Assert(Block(CampaignPreflight.Evaluate(p,o,false,""),"target_actions"));o.Farm.ActionsKnown=true;o.Farm.KnownActionsMask=1;Assert(Block(CampaignPreflight.Evaluate(p,o,false,""),"target_actions"));});
        Test("known configured actions may wait for cooldown or temporary usability",delegate{var p=Ready();p.Battle.SkillSequence="12";var o=SavedMonster(p);o.Farm.KnownActionsMask=3;o.Farm.ReadyActionsMask=o.Farm.UsableActionsMask=0;var r=CampaignPreflight.Evaluate(p,o,false,"");Assert(r.ReadyToArm&&r.Checks.Any(c=>c.Code=="target_actions"&&c.State=="pending"));o.Farm.ReadyActionsMask=o.Farm.UsableActionsMask=3;r=CampaignPreflight.Evaluate(p,o,false,"");Assert(r.ReadyToArm&&r.Checks.Any(c=>c.Code=="target_actions"&&c.State=="pass"));});
        Test("unselected future targets do not require action observations before patrol",delegate{var o=CampaignFixtures.Sample();o.Farm.ActionsKnown=false;o.Farm.KnownActionsMask=0;var r=CampaignPreflight.Evaluate(Ready(),o,false,"");Assert(r.ReadyToArm&&r.Checks.Any(c=>c.Code=="target_actions"&&c.State=="pending"));});
        Test("portrait requirement cannot pass missing reference templates",delegate{var p=Ready();p.Settings.RequirePortraitMatch=true;Assert(Block(CampaignPreflight.Evaluate(p,CampaignFixtures.Sample(),false,""),"portraits"));});
        Test("normal unopened future merchant and bag slots are not forced visible",delegate{var o=CampaignFixtures.Sample();o.InventoryKnown=false;var r=CampaignPreflight.Evaluate(Ready(),o,false,"");Assert(r.ReadyToArm&&r.Checks.Any(c=>c.Code=="inventory"&&c.State=="pending"));});
        Test("malformed plan fields cannot throw while rendering the failed check",delegate{foreach(int variant in new[]{0,1,2}){var p=Ready();if(variant==0)p.StartIndex=999;else if(variant==1)p.Battle.Calibration=null;else p.FarmRoute.Points=null;var r=CampaignPreflight.Evaluate(p,CampaignFixtures.Sample(),false,"");Assert(!r.ReadyToArm&&Block(r,"plan"));}});
        Console.WriteLine("Campaign preflight tests: "+passed+" passed, "+failed+" failed. Read-only; no input backend.");return failed==0?0:1;
    }
}
